Soluție


Laborator (c) Simularea unui joc și formula teoretică; regăsim \(2/3\), \(0.731\), \(0.7\) și \(0.872\).





joc_ruina &lt;- function(k, N, p) {
  capital &lt;- k   # capitalul, rundă cu rundă
  while (k &gt; 0 && k &lt; N) {
    k &lt;- k + ifelse(runif(1) &lt; p, 1, -1)
    capital &lt;- c(capital, k)
  }
  capital
}



p_ruina &lt;- function(k, N, p) {
  if (p == 0.5) return(1 - k / N)
  r &lt;- (1 - p) / p
  (r^k - r^N) / (1 - r^N)
}
c(p_ruina(1, 3, 0.5), p_ruina(1, 3, 0.45),
  p_ruina(3, 10, 0.5), p_ruina(3, 10, 0.45))

#&gt; [1] 0.6667 0.7309 0.7000 0.8717




